import { test, expect } from '@playwright/test';

test.describe('Empty State Illustration - Table List', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/table-list');
  });

  test('should display empty state illustration when table has no data', async ({ page }) => {
    // Intercept the API call and return an empty response
    await page.route('**/api/table/data', (route) => {
      route.abort('blockedbyclient');
    });

    // Click the refresh button to trigger the empty state
    const refreshButton = page.getByRole('button', { name: /refresh/i });
    await refreshButton.click();

    // Wait for the empty state to load
    await page.waitForLoadState('networkidle');

    // Verify the empty state illustration is visible
    const emptyStateIllustration = page.getByTestId('empty-state-illustration');
    await expect(emptyStateIllustration).toBeVisible();

    // Verify the empty state message is displayed
    const emptyStateMessage = page.getByText(/no data available/i);
    await expect(emptyStateMessage).toBeVisible();

    // Verify the table container is empty
    const tableContainer = page.getByTestId('table-container');
    await expect(tableContainer).toBeVisible();
    const tableRows = page.getByRole('row');
    const rowCount = await tableRows.count();
    expect(rowCount).toBe(0);

    // Verify the empty state illustration has the correct alt text
    const illustrationAlt = page.getByTestId('empty-state-illustration').first().getAttribute('alt');
    expect(illustrationAlt).toContain('no data');
  });

  test('should hide empty state illustration when data is loaded', async ({ page }) => {
    // Intercept the API call and return a successful response with data
    await page.route('**/api/table/data', (route) => {
      route.continue();
    });

    // Click the refresh button to load data
    const refreshButton = page.getByRole('button', { name: /refresh/i });
    await refreshButton.click();

    // Wait for the data to load
    await page.waitForLoadState('networkidle');

    // Verify the empty state illustration is no longer visible
    const emptyStateIllustration = page.getByTestId('empty-state-illustration');
    await expect(emptyStateIllustration).not.toBeVisible();

    // Verify the table container is visible and contains data
    const tableContainer = page.getByTestId('table-container');
    await expect(tableContainer).toBeVisible();
    const tableRows = page.getByRole('row');
    const rowCount = await tableRows.count();
    expect(rowCount).toBeGreaterThan(0);

    // Verify the empty state message is no longer visible
    const emptyStateMessage = page.getByText(/no data available/i);
    await expect(emptyStateMessage).not.toBeVisible();

    // Verify the table header is visible
    const tableHeader = page.getByRole('columnheader', { name: /name/i });
    await expect(tableHeader).toBeVisible();
  });
});
